def transform(grid):
    g = np.array(grid)
    bg = background(g)
    vals, counts = np.unique(g[g != bg], return_counts=True)
    order = np.argsort(-counts)
    block = int(vals[order[0]])
    noise = [int(v) for v in vals if v != block]
    H, W = g.shape
    isnoise = np.isin(g, noise)

    def look(y, x, dy, dx):
        y += dy; x += dx
        while 0 <= y < H and 0 <= x < W and isnoise[y, x]:
            y += dy; x += dx
        return 0 <= y < H and 0 <= x < W and g[y, x] == block

    def isblock(y, x):
        return 0 <= y < H and 0 <= x < W and (g[y, x] == block or isnoise[y, x])

    def inside_test(y, x):
        L, R = look(y, x, 0, -1), look(y, x, 0, 1)
        U, D = look(y, x, -1, 0), look(y, x, 1, 0)
        if (L and R) or (U and D):
            return True
        for dx, hx in ((-1, L), (1, R)):
            for dy, vy in ((-1, U), (1, D)):
                if hx and vy and isblock(y + dy, x + dx):
                    return True
        return False

    out = g.copy()
    inside, outside = [], []
    for y in range(H):
        for x in range(W):
            if isnoise[y, x]:
                (inside if inside_test(y, x) else outside).append((y, x))
    for y, x in inside:
        out[y, x] = block
    emit(out, "Noise pixels lying inside a rectangle (block on both sides of an axis, or a corner completing a block diagonal) are repaired to the block colour.")
    for y, x in outside:
        out[y, x] = bg
    emit(out, "Remaining noise pixels outside the rectangles are erased to background.")
    return out
